# ---- FT review, seventh pass (FT reviewer 7, 2026-11-21): dividends to non-residents changed during 2025 (year in force) ----
# The 15 % came from PwC's Jamaica page reviewed 29 Sep 2026. Dated copies (Internet Archive, ftreview/rv7/fetch/):
# reviewed 3 March 2025 (capture 2025-08-03): non-treaty non-resident corporations 33 1/3 %, individuals 25 % on dividends;
# reviewed 12 August 2025 (capture 2025-12-16): 15 % for both. The rate changed during 2025; the amending provision and its
# date are not held, so no part of 2025 can be priced from a read rule: the dividend rule is withdrawn (grade C).
S["wht"] = [r for r in S["wht"] if r.get("kind") != "dividend"]
S["guards"] = [g for g in S["guards"] if "kind := .dividend" not in g]
S["unsupported"] = [u for u in S["unsupported"] if not u[1].startswith("dividends to non-residents: the ITA provision was not found")] + [
    ["g.entity == .company && g.company.paymentsAbroad.any (·.kind == .dividend)",
     "1200 withholding on dividends to non-residents not computed (grade C): the rate changed during 2025 (PwC: 33 1/3 % companies / 25 % individuals as reviewed 3 March 2025; 15 % as reviewed 12 August 2025); the amending provision and its date not read"]]
S["doc"] += ("\n\n**FT review 7 (year in force):** dividends to non-residents: PwC reviewed 3 March 2025 (Internet Archive 2025-08-03) gives "
             "33 1/3 % (companies) and 25 % (individuals), reviewed 12 August 2025 (Internet Archive 2025-12-16) 15 %: a change during 2025 whose "
             "provision and date are not held; the rule is withdrawn (grade C).")
for t in S["taxes"]:
    if t.get("tax") == "Withholding on dividends to non-residents":
        t["grade"] = "C"
        t["statute"] = "not reached: Income Tax Act provision not found; the rate changed during 2025 (PwC reviewed 3 Mar 2025: 33 1/3 % / 25 %; reviewed 12 Aug 2025: 15 %), the amending provision and its date not read"
        t["dated"] = "PwC Worldwide Tax Summaries Jamaica, corporate withholding taxes: Internet Archive captures 2025-08-03 (reviewed 2025-03-03) and 2025-12-16 (reviewed 2025-08-12); FT review 7"
        t["unsupported"] = ["2025 rate not established (changed during the year)"]
